// TelegramServiceServer is the server API for TelegramService service.
// All implementations should embed UnimplementedTelegramServiceServer
// for forward compatibility.
//
// TelegramService proxies the Telegram Bot API
// (https://core.telegram.org/bots/api).
//
// Authentication: TELEGRAM_BOT_TOKEN env var. The token is embedded in the
// path (e.g. https://api.telegram.org/bot<token>/sendMessage). Responses are
// returned as google.protobuf.Struct since the API surface is large and
// heavily polymorphic.
type TelegramServiceServer interface {
	// getMe -- verify token and return basic info about the bot.
	GetMe(context.Context, *GetMeRequest) (*structpb.Struct, error)
	// logOut -- log out from the cloud Bot API server before launching the bot locally.
	LogOut(context.Context, *LogOutRequest) (*structpb.Struct, error)
	// close -- close the bot instance.
	Close(context.Context, *CloseRequest) (*structpb.Struct, error)
	// sendMessage -- send a text message.
	SendMessage(context.Context, *SendMessageRequest) (*structpb.Struct, error)
	// forwardMessage -- forward messages of any kind.
	ForwardMessage(context.Context, *ForwardMessageRequest) (*structpb.Struct, error)
	// copyMessage -- copy a message without quoting it.
	CopyMessage(context.Context, *CopyMessageRequest) (*structpb.Struct, error)
	// sendPhoto -- send a photo by URL or file_id.
	SendPhoto(context.Context, *SendPhotoRequest) (*structpb.Struct, error)
	// sendAudio -- send audio.
	SendAudio(context.Context, *SendAudioRequest) (*structpb.Struct, error)
	// sendDocument -- send a document.
	SendDocument(context.Context, *SendDocumentRequest) (*structpb.Struct, error)
	// sendVideo -- send a video.
	SendVideo(context.Context, *SendVideoRequest) (*structpb.Struct, error)
	// sendAnimation -- send an animation.
	SendAnimation(context.Context, *SendAnimationRequest) (*structpb.Struct, error)
	// sendVoice -- send a voice note.
	SendVoice(context.Context, *SendVoiceRequest) (*structpb.Struct, error)
	// sendVideoNote -- send a video note.
	SendVideoNote(context.Context, *SendVideoNoteRequest) (*structpb.Struct, error)
	// sendLocation -- send a point on the map.
	SendLocation(context.Context, *SendLocationRequest) (*structpb.Struct, error)
	// sendVenue -- send a venue.
	SendVenue(context.Context, *SendVenueRequest) (*structpb.Struct, error)
	// sendContact -- send a contact.
	SendContact(context.Context, *SendContactRequest) (*structpb.Struct, error)
	// sendPoll -- send a poll.
	SendPoll(context.Context, *SendPollRequest) (*structpb.Struct, error)
	// sendDice -- send a dice with a random value.
	SendDice(context.Context, *SendDiceRequest) (*structpb.Struct, error)
	// sendChatAction -- send a "typing" indicator.
	SendChatAction(context.Context, *SendChatActionRequest) (*structpb.Struct, error)
	// editMessageText -- edit a text or game message.
	EditMessageText(context.Context, *EditMessageTextRequest) (*structpb.Struct, error)
	// editMessageCaption -- edit caption of a message.
	EditMessageCaption(context.Context, *EditMessageCaptionRequest) (*structpb.Struct, error)
	// editMessageReplyMarkup -- edit only the reply markup.
	EditMessageReplyMarkup(context.Context, *EditMessageReplyMarkupRequest) (*structpb.Struct, error)
	// deleteMessage -- delete a single message.
	DeleteMessage(context.Context, *DeleteMessageRequest) (*structpb.Struct, error)
	// deleteMessages -- delete multiple messages.
	DeleteMessages(context.Context, *DeleteMessagesRequest) (*structpb.Struct, error)
	// getChat -- get up-to-date info about the chat.
	GetChat(context.Context, *GetChatRequest) (*structpb.Struct, error)
	// getChatAdministrators -- list admins of a chat.
	GetChatAdministrators(context.Context, *GetChatAdministratorsRequest) (*structpb.Struct, error)
	// getChatMemberCount -- get the number of members in a chat.
	GetChatMemberCount(context.Context, *GetChatMemberCountRequest) (*structpb.Struct, error)
	// getChatMember -- get info about a member of a chat.
	GetChatMember(context.Context, *GetChatMemberRequest) (*structpb.Struct, error)
	// banChatMember -- ban a member from a group / channel.
	BanChatMember(context.Context, *BanChatMemberRequest) (*structpb.Struct, error)
	// unbanChatMember -- unban a previously banned user.
	UnbanChatMember(context.Context, *UnbanChatMemberRequest) (*structpb.Struct, error)
	// restrictChatMember -- restrict a user in a supergroup.
	RestrictChatMember(context.Context, *RestrictChatMemberRequest) (*structpb.Struct, error)
	// promoteChatMember -- promote or demote a chat administrator.
	PromoteChatMember(context.Context, *PromoteChatMemberRequest) (*structpb.Struct, error)
	// setChatTitle -- change the title of a chat.
	SetChatTitle(context.Context, *SetChatTitleRequest) (*structpb.Struct, error)
	// setChatDescription -- change the description of a chat.
	SetChatDescription(context.Context, *SetChatDescriptionRequest) (*structpb.Struct, error)
	// pinChatMessage -- pin a message in a chat.
	PinChatMessage(context.Context, *PinChatMessageRequest) (*structpb.Struct, error)
	// unpinChatMessage -- unpin a message.
	UnpinChatMessage(context.Context, *UnpinChatMessageRequest) (*structpb.Struct, error)
	// unpinAllChatMessages -- unpin all pinned messages in a chat.
	UnpinAllChatMessages(context.Context, *UnpinAllChatMessagesRequest) (*structpb.Struct, error)
	// leaveChat -- have the bot leave a group/channel.
	LeaveChat(context.Context, *LeaveChatRequest) (*structpb.Struct, error)
	// getUpdates -- long-poll for incoming updates.
	GetUpdates(context.Context, *GetUpdatesRequest) (*structpb.Struct, error)
	// setWebhook -- set a webhook URL for incoming updates.
	SetWebhook(context.Context, *SetWebhookRequest) (*structpb.Struct, error)
	// deleteWebhook -- remove the configured webhook.
	DeleteWebhook(context.Context, *DeleteWebhookRequest) (*structpb.Struct, error)
	// getWebhookInfo -- get current webhook status.
	GetWebhookInfo(context.Context, *GetWebhookInfoRequest) (*structpb.Struct, error)
	// getFile -- get file info for downloading.
	GetFile(context.Context, *GetFileRequest) (*structpb.Struct, error)
	// answerCallbackQuery -- answer a callback query from an inline keyboard.
	AnswerCallbackQuery(context.Context, *AnswerCallbackQueryRequest) (*structpb.Struct, error)
	// setMyCommands -- set the list of bot commands.
	SetMyCommands(context.Context, *SetMyCommandsRequest) (*structpb.Struct, error)
	// getMyCommands -- get the list of bot commands.
	GetMyCommands(context.Context, *GetMyCommandsRequest) (*structpb.Struct, error)
	// deleteMyCommands -- delete commands for a scope.
	DeleteMyCommands(context.Context, *DeleteMyCommandsRequest) (*structpb.Struct, error)
	// setMyDescription -- set the bot description.
	SetMyDescription(context.Context, *SetMyDescriptionRequest) (*structpb.Struct, error)
	// setMyShortDescription -- set the bot short description.
	SetMyShortDescription(context.Context, *SetMyShortDescriptionRequest) (*structpb.Struct, error)
	// sendInvoice -- send an invoice (for payments).
	SendInvoice(context.Context, *SendInvoiceRequest) (*structpb.Struct, error)
	// exportChatInviteLink -- generate a new primary invite link.
	ExportChatInviteLink(context.Context, *ExportChatInviteLinkRequest) (*structpb.Struct, error)
	// createChatInviteLink -- create an additional invite link.
	CreateChatInviteLink(context.Context, *CreateChatInviteLinkRequest) (*structpb.Struct, error)
}

